// One folder per run so concurrent submissions never collide.
const runId = ($json.submittedAt || String(Date.now())).replace(/[^a-zA-Z0-9]/g, '');
const dir = `/tmp/loudnorm-${runId}`;

// Don't assume the binary property name the Form Trigger gave the uploaded file -
// find whatever key is actually there so this keeps working across n8n versions.
const binKeys = Object.keys($input.item.binary || {});
if (binKeys.length === 0) {
  throw new Error('No file was uploaded - the Audio File field came through empty.');
}
const binaryKey = binKeys[0];
const upload = $input.item.binary[binaryKey];

const originalName = upload.fileName || 'audio';
const extMatch = originalName.match(/\.([a-zA-Z0-9]+)$/);
const ext = extMatch ? extMatch[1] : 'mp3';

// "-14 (YouTube, TikTok, Instagram, Spotify)" -> -14
const targetLabel = $json['Target Loudness'] || '-14';
const targetMatch = targetLabel.match(/-?\d+(\.\d+)?/);
if (!targetMatch) throw new Error(`Could not read a target LUFS number from "${targetLabel}".`);
const targetLufs = Number(targetMatch[0]);

// "Off (default)" / "80Hz (...)" / "120Hz (...)" -> null / 80 / 120
const lowCutLabel = $json['Low-Cut Filter (rumble/handling noise)'] || 'Off (default)';
let highpassHz = null;
if (lowCutLabel.startsWith('80')) highpassHz = 80;
else if (lowCutLabel.startsWith('120')) highpassHz = 120;
const afPrefix = highpassHz ? `highpass=f=${highpassHz},` : '';

return {
  json: {
    ...$json,
    dir,
    binaryKey,
    inputPath: `${dir}/input.${ext}`,
    outputPath: `${dir}/normalized.m4a`,
    targetLufs,
    highpassHz,
    afPrefix,
  },
  binary: $input.item.binary,
};

// Create the temp folder (Execute Command) wipes json + binary - re-attach both
// from Prepare Run so the uploaded file survives to the write-to-disk step.
const run = $('Prepare Run').item.json;
return { json: run, binary: $('Prepare Run').item.binary };

// FFmpeg's loudnorm filter prints a JSON stats block to stderr when it runs -
// this is the ONLY place the real measured-before/after numbers exist.
const cmdResult = $json;
const run = $('Prepare Run').item.json;

if (cmdResult.exitCode !== undefined && cmdResult.exitCode !== 0) {
  throw new Error('FFmpeg failed: ' + (cmdResult.stderr || '').slice(-500));
}

const stderr = cmdResult.stderr || '';
const match = stderr.match(/\{[^{}]*"input_i"[\s\S]*?\}/);
if (!match) {
  throw new Error('Could not find loudnorm stats in FFmpeg output. Last output: ' + stderr.slice(-500));
}

let stats;
try {
  stats = JSON.parse(match[0]);
} catch (e) {
  throw new Error('Failed to parse loudnorm JSON stats: ' + e.message);
}

return {
  json: {
    inputLoudnessLUFS: Number(stats.input_i),
    inputTruePeakDB: Number(stats.input_tp),
    outputLoudnessLUFS: Number(stats.output_i),
    outputTruePeakDB: Number(stats.output_tp),
    targetLoudnessLUFS: run.targetLufs,
    normalizationType: stats.normalization_type,
    lowCutHz: run.highpassHz,
    outputPath: run.outputPath,
  },
};

// Read Normalized Audio (Read/Write File) replaces json with file metadata only -
// merge back the loudness report so the buyer gets numbers AND the file together.
const report = $('Parse the loudness report').item.json;
return {
  json: { ...report, file: $json },
  binary: $input.item.binary,
};
